"""Offline expedition preparation; no framework or remote assets required."""
EXPEDITION_HTML = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>远征手册 · PokeTactics</title><style>
:root{--ink:#243b33;--paper:#f4f0e4;--line:#c4cbb8;--green:#315b46;--muted:#626f62;--orange:#a64d24}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 'PingFang SC','Microsoft YaHei',sans-serif}main{max-width:1176px;padding:26px 32px 70px;margin:auto}a{color:var(--green);text-underline-offset:4px}nav{display:flex;gap:22px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:16px}.brand{font:bold 16px Georgia,serif;letter-spacing:2px;margin-right:auto}header{display:grid;grid-template-columns:1.3fr 1fr;gap:30px;align-items:end;padding:36px 0 28px}h1{font:500 42px/1.3 'Songti SC',serif;margin:6px 0 13px}h2{font:600 24px 'Songti SC',serif;margin:0 0 18px}h3,p{margin:0 0 10px}.eyebrow{font:12px monospace;letter-spacing:2px;color:var(--green)}.muted,small{color:var(--muted)}.stats{display:flex;justify-content:space-between;border-top:2px solid var(--green);padding:16px 4px}.stat b{display:block;font:30px Georgia,serif}.stat span{font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:30px}.sheet{background:#faf8ef;border:1px solid var(--line);padding:24px}.sectiontitle{display:flex;justify-content:space-between;align-items:baseline}.step{color:var(--orange);font:13px monospace}.partners{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}button,select,input{font:inherit;color:inherit}button{cursor:pointer;border:1px solid var(--line);background:transparent;padding:10px 14px}button:hover:not(:disabled){border-color:var(--green);background:#e6ecde}button:focus-visible,a:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #b96c33;outline-offset:3px}button:disabled{cursor:not-allowed;color:#7a8077}.partner{padding:12px 2px 8px;position:relative;text-align:center}.partner img{display:block;image-rendering:pixelated;width:68px;height:68px;object-fit:contain;margin:0 auto 6px}.partner[aria-pressed=true]{background:#e0ead6;border:2px solid var(--green);padding:11px 1px 7px}.partner:disabled img{filter:grayscale(1);opacity:.45}.partner span{display:block;font-size:13px}.partner small{font-size:10px}.trait{margin-top:18px;min-height:132px;border-left:3px solid var(--green);padding:12px 16px;background:#edf0e3}.trait strong{display:block;margin-bottom:5px}.trait p{font-size:13px}.loadout{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:26px}label{display:block;font-size:13px;font-weight:bold}select,input{width:100%;margin:6px 0 8px;border:1px solid var(--line);background:#fffdf5;padding:10px}.loadout p{font-size:12px;min-height:42px}.launch{display:flex;gap:16px;align-items:center;margin-top:20px;border-top:1px solid var(--line);padding-top:22px}.launch label{max-width:135px}.primary{background:var(--green);color:#fffbe9;border-color:var(--green);font-weight:bold;flex:1;padding:14px}.primary:hover:not(:disabled){background:#264837;color:white}.primary:disabled{background:#d4d9ca}.note{font-size:12px;margin-top:12px}.challenges{padding:21px;background:#e5ebdb;border-top:4px solid var(--green)}.challenge{border-top:1px solid #b9c5af;padding:15px 0}.challenge b{font-size:14px}.challenge p{font-size:12px;margin:4px 0}.progress{height:4px;background:#c8d0c0;margin-top:10px}.progress i{display:block;height:100%;background:var(--green)}.reward{color:var(--orange)}.challenge.done .reward{color:var(--green)}.collection{margin-top:32px}.dex{display:grid;grid-template-columns:repeat(12,1fr);gap:5px}.dexitem{text-align:center;border-bottom:2px solid transparent;font-size:10px;padding:7px 0}.dexitem img{width:44px;height:44px;object-fit:contain;image-rendering:pixelated;display:block;margin:auto}.dexitem.unseen img{filter:grayscale(1);opacity:.25}.dexitem.won{border-color:var(--green)}.dexitem.fielded{background:#e1e9d9}.collection summary{cursor:pointer;font-weight:bold;padding:10px 0}.error{color:#9d352b;padding:12px 0;white-space:pre-wrap}.error:empty{display:none}.footer{margin-top:28px;border-top:1px solid var(--line);padding-top:18px;font-size:12px}.importbar{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-top:12px}.importbar input{width:240px}.import-preview{padding:14px;background:#ece5d1} [hidden]{display:none!important}
@media(max-width:850px){main{padding:20px 18px 40px}.layout{grid-template-columns:1fr}.challenges{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.challenges h2{grid-column:1/-1}.dex{grid-template-columns:repeat(8,1fr)}header{grid-template-columns:1fr}.stats{max-width:500px}h1{font-size:36px}}@media(max-width:480px){.sheet{padding:16px}.partners{grid-template-columns:repeat(3,1fr)}.loadout{grid-template-columns:1fr}.trait{min-height:0}.dex{grid-template-columns:repeat(6,1fr)}nav{gap:12px;font-size:12px}.brand{font-size:12px}.challenges{display:block}.launch{gap:10px}}
</style></head><body><main>
<nav><span class="brand">POKÉTACTICS / FIELD NOTES</span><a href="/demo">继续对局</a><a href="/device">三键设备试玩</a><a href="/animation-lab">动画预览</a></nav>
<header><div><span class="eyebrow">OFFLINE EXPEDITION · 远征手册</span><h1>带上搭档，再出发。</h1><p class="muted">每一次上场，都会留下发现。失败也保留挑战进度，<br>逐步解锁新的搭档、招式机器和开局装备。</p></div><div id="stats" class="stats" aria-label="本机档案统计">正在读取档案…</div></header>
<div id="error" class="error" role="alert"></div>
<div class="layout"><section class="sheet"><div class="sectiontitle"><h2>这次和谁一起？</h2><span class="step">01 / 主搭档</span></div>
<div id="partners" class="partners" aria-label="主搭档选择"></div><div id="trait" class="trait">读取搭档资料…</div>
<div class="loadout"><div><label for="technique">02 / 学习招式</label><select id="technique" disabled><option value="">不携带招式机器</option></select><p id="tech-note" class="muted">解锁后为相容搭档学习，保留原本的大招。</p></div><div><label for="item">03 / 开局装备</label><select id="item" disabled><option value="">不携带装备</option></select><p id="item-note" class="muted">装备占用搭档的一格道具栏，可在准备阶段卸下。</p></div></div>
<div class="launch"><label for="seed">随机种子（可空）<input id="seed" type="number" placeholder="例如 7"></label><button class="primary" id="start" disabled>出发 · 开始远征 →</button></div>
<p class="note muted">所选家族按部署顺序第一只上场棋子获得搭档特性，进化后继续生效；同族多只不叠加。其他宝可梦照常释放自己的技能。</p><p class="note muted">本模式使用同费用基础预算 v1（实验中），种族值决定分配倾向。技能、射程和羁绊仍需持续校准。<a href="/demo?new=classic">新开经典对局</a>，沿用原规则。</p></section>
<aside class="challenges"><h2>下一次发现</h2><div id="challenges">正在读取挑战…</div></aside></div>
<details class="collection" open><summary>野外图鉴 <span class="muted">· 灰色未见 / 浅绿已上场 / 下划线随队获胜</span></summary><div id="dex" class="dex"></div></details>
<footer class="footer"><b>只保存在这台设备。</b> 档案与单局存档分别备份；解锁增加选择，不永久叠加攻防。现有 84 只商店宝可梦仍然可以抽到。
<div class="importbar"><a href="/api/expedition/backup" download="PokeTactics-profile.ptsave">下载档案备份</a><a href="/api/expedition/backup?checkpoint=1" download="PokeTactics-profile-before-import.ptsave">下载导入前检查点</a><label for="profile-file">导入档案备份</label><input id="profile-file" type="file" accept=".ptsave,application/json"></div><div id="import-preview" class="import-preview" hidden><p id="import-info"></p><button id="confirm-import">导入并备份现有档案</button><button id="cancel-import">取消</button></div></footer>
</main><script>
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=null,partner=6,busy=false,pending=null;
function error(s){$('error').textContent=s||'';}
function render(){const s=data.stats;$('stats').innerHTML=[['完成远征',s.finished],['已见物种',s.seen],['上场物种',s.fielded],['冠军',s.wins]].map(([label,n])=>'<div class="stat"><b>'+Number(n)+'</b><span>'+label+'</span></div>').join('');
$('partners').innerHTML=data.partners.map(p=>'<button class="partner" data-id="'+p.id+'" aria-pressed="'+(p.id===partner)+'" '+(!p.unlocked?'disabled':'')+'><img src="/demo/sprite/'+p.id+'.png" alt=""><span>'+esc(p.name)+'</span><small>'+(p.unlocked?'可出战':'挑战解锁')+'</small></button>').join('');
$('partners').querySelectorAll('button').forEach(b=>b.onclick=()=>{partner=Number(b.dataset.id);render();});
const p=data.partners.find(p=>p.id===partner);$('trait').innerHTML='<strong>'+esc(p.description)+'</strong><p>开局携带 '+esc(p.starter_name)+'，按普通商店价格支付 '+p.cost+' 金。与队友一起上场，让特性发挥作用。</p>';
const old=$('technique').value;$('technique').innerHTML='<option value="">不携带招式机器</option>'+data.techniques.map(t=>'<option value="'+esc(t.id)+'" '+(!t.unlocked||!p.techniques.includes(t.id)?'disabled':'')+'>'+esc(t.name)+(t.unlocked?(p.techniques.includes(t.id)?'':' · 不相容'):' · 未解锁')+'</option>').join('');if(data.techniques.some(t=>t.id===old&&t.unlocked&&p.techniques.includes(t.id)))$('technique').value=old;
const oldItem=$('item').value;$('item').innerHTML='<option value="">不携带装备</option>'+data.items.map(t=>'<option value="'+esc(t.id)+'" '+(!t.unlocked?'disabled':'')+'>'+esc(t.name)+(t.unlocked?'':' · 未解锁')+'</option>').join('');if(data.items.some(t=>t.id===oldItem&&t.unlocked))$('item').value=oldItem;
$('technique').disabled=$('item').disabled=false;$('start').disabled=busy;describe();
$('challenges').innerHTML=data.challenges.map(c=>'<div class="challenge '+(c.unlocked?'done':'')+'"><b>'+esc(c.name)+'</b><p>'+esc(c.description)+'</p><p class="reward">'+(c.unlocked?'已解锁 · ':'解锁 · ')+esc(c.rewards.join(' / '))+'</p><small>'+Math.min(c.progress,c.target)+' / '+c.target+'</small><div class="progress"><i style="width:'+Math.min(100,c.progress/c.target*100)+'%"></i></div></div>').join('');
$('dex').innerHTML=data.dex.map(d=>'<div class="dexitem '+(!d.seen?'unseen ':'' )+(d.fielded?'fielded ':'')+(d.won?'won':'')+'" title="'+esc(d.name)+' · '+(d.won?'随队获胜':d.fielded?'已上场':d.seen?'已见':'未见')+'"><img loading="lazy" src="/demo/sprite/'+d.id+'.png" alt=""><span>'+esc(d.name)+'</span></div>').join('');}
function describe(){$('tech-note').textContent=data.techniques.find(t=>t.id===$('technique').value)?.description||'获得招式机器后，为相容主搭档学习；原本大招保留。';$('item-note').textContent=data.items.find(t=>t.id===$('item').value)?.description||'装备占用搭档的一格道具栏，可在准备阶段卸下。';}
$('technique').onchange=$('item').onchange=describe;
async function load(){try{const j=await(await fetch('/api/expedition/profile')).json();if(!j.ok)throw Error(j.error);data=j;render();}catch(e){error(e.message);$('start').disabled=true;}}
$('start').onclick=async()=>{if(busy||!data)return;busy=true;$('start').disabled=true;error('');try{const q=new URLSearchParams({cmd:'new',mode:'expedition',partner,technique:$('technique').value,item:$('item').value,seed:$('seed').value});const j=await(await fetch('/api/demo/action?'+q)).json();if(!j.ok)throw Error(j.error);try{localStorage.setItem('poketactics.slot',j.sid);}catch(e){}location.href='/demo?sid='+encodeURIComponent(j.sid);}catch(e){error(e.message);busy=false;$('start').disabled=false;}};
async function importRequest(inspect){return(await fetch('/api/expedition/import'+(inspect?'/inspect':''),{method:'POST',headers:{'X-PokeTactics-Import':'1','Content-Type':'application/json'},body:pending})).json();}
$('profile-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024){error('档案备份不能超过 8MB');return;}try{pending=await file.text();const j=await importRequest(true);if(!j.ok)throw Error(j.error);$('import-info').textContent='此档案包含 '+j.stats.finished+' 局已完成对局、'+j.stats.fielded+' 种上场宝可梦。将替换本机档案，导入前自动保留一份检查点。';$('import-preview').hidden=false;}catch(e){pending=null;error(e.message);}};
$('cancel-import').onclick=()=>{pending=null;$('import-preview').hidden=true;$('profile-file').value='';};
$('confirm-import').onclick=async()=>{if(!pending)return;$('confirm-import').disabled=true;try{const j=await importRequest(false);if(!j.ok)throw Error(j.error);$('cancel-import').click();await load();error('');}catch(e){error(e.message);}finally{$('confirm-import').disabled=false;}};
load();
</script></body></html>'''
